SELECT uint64 = float32 AS c0, toTypeName(uint64 = float32) AS t0, uint64 != float32 AS c1, toTypeName(uint64 != float32) AS t1, uint64 < float32 AS c2, toTypeName(uint64 < float32) AS t2, uint64 <= float32 AS c3, toTypeName(uint64 <= float32) AS t3, uint64 > float32 AS c4, toTypeName(uint64 > float32) AS t4, uint64 >= float32 AS c5, toTypeName(uint64 >= float32) AS t5 FROM he24.numeric ORDER BY row_id
